import { openDatabase, rowToJob } from './db.ts';

const db = openDatabase();
let stopping = false;
for (const signal of ['SIGINT', 'SIGTERM'] as const) process.on(signal, () => { stopping = true; });
const heartbeat = db.prepare('INSERT INTO worker_heartbeat(id,at) VALUES(1,?) ON CONFLICT(id) DO UPDATE SET at=excluded.at');
const beat = () => heartbeat.run(Date.now());
beat();
const timer = setInterval(beat, 500);
// An interrupted attempt is restarted from its first step when a worker comes back.
db.prepare("UPDATE jobs SET status='queued', progress_completed=0, updated_at=?, available_at=0 WHERE status='running'").run(new Date().toISOString());
console.log('worker started');

while (!stopping) {
  beat();
  const now = Date.now();
  db.exec('BEGIN IMMEDIATE');
  let row: Record<string, unknown> | undefined;
  try {
    row = db.prepare("SELECT * FROM jobs WHERE status='queued' AND available_at<=? ORDER BY created_at ASC, rowid ASC LIMIT 1").get(now) as Record<string, unknown> | undefined;
    if (row) {
      const updated = new Date().toISOString();
      const id = String(row.id);
      db.prepare("UPDATE jobs SET status='running', attempts=attempts+1, progress_completed=0, updated_at=? WHERE id=? AND status='queued'").run(updated, id);
      row = db.prepare('SELECT * FROM jobs WHERE id=?').get(id) as Record<string, unknown>;
    }
    db.exec('COMMIT');
  } catch (e) { db.exec('ROLLBACK'); throw e; }
  if (!row) { await sleep(100); continue; }
  const job = rowToJob(row);
  const attempt = job.attempts;
  if (attempt <= job.failAttempts) {
    await sleep(100);
    const updated = new Date().toISOString();
    if (attempt >= 3) db.prepare("UPDATE jobs SET status='failed', error='transient failure', result_output=NULL, progress_completed=0, updated_at=? WHERE id=? AND status='running'").run(updated, job.id);
    else db.prepare("UPDATE jobs SET status='queued', progress_completed=0, updated_at=?, available_at=? WHERE id=? AND status='running'").run(updated, Date.now() + 500, job.id);
    continue;
  }
  for (let step = 1; step <= job.steps && !stopping; step++) {
    await sleep(100);
    const updated = new Date().toISOString();
    db.prepare("UPDATE jobs SET progress_completed=?, updated_at=? WHERE id=? AND status='running'").run(step, updated, job.id);
  }
  if (stopping) break;
  const updated = new Date().toISOString();
  db.prepare("UPDATE jobs SET status='completed', result_output=?, error=NULL, progress_completed=steps, updated_at=? WHERE id=? AND status='running'").run(job.input.toUpperCase(), updated, job.id);
}
clearInterval(timer);
db.close();

