24	<body>
25	  <h1>Job tracker</h1>
26	  <p class="subtle">Submit text to process it in a background worker.</p>
27	  <form data-testid="job-form" id="job-form">
28	    <label>Input <input data-testid="job-input" name="input" required maxlength="1000"></label>
29	    <label>Steps <input data-testid="job-steps" name="steps" type="number" min="1" max="20" value="5" required></label>
30	    <label>Fail attempts <input data-testid="job-fail-attempts" name="failAttempts" type="number" min="0" max="5" value="0" required></label>
31	    <button data-testid="job-submit" type="submit">Submit job</button>
32	  </form>
33	  <div data-testid="form-error" id="form-error" role="alert"></div>
34	  <h2>Jobs</h2>
35	  <ul data-testid="job-list" id="jobs"></ul>
36	<script>
37	(() => {
38	  const form = document.querySelector('[data-testid="job-form"]');
39	  const errorRegion = document.querySelector('[data-testid="form-error"]');
40	  const list = document.querySelector('[data-testid="job-list"]');
41	  const field = (name) => form.elements.namedItem(name);
42	  function text(parent, tag, value, testid) {
43	    const el = document.createElement(tag); if (testid) el.dataset.testid = testid;
44	    el.textContent = value; parent.append(el); return el;
45	  }
46	  function render(jobs) {
47	    list.replaceChildren();
48	    for (const job of jobs) {
49	      const li = document.createElement('li'); li.dataset.testid = 'job-item'; li.dataset.jobId = job.id; li.className = 'job';
50	      const title = document.createElement('strong'); title.textContent = job.input; li.append(title);
51	      text(li, 'span', job.status, 'job-status');
52	      text(li, 'small', `${job.progress.completed}/${job.progress.total}`, 'job-progress');
53	      const output = job.result ? job.result.output : job.status === 'failed' ? job.error : '';
54	      text(li, 'span', output || '', 'job-result').className = 'job-output';
55	      list.append(li);
56	    }
57	  }
58	  async function refresh() {
59	    try { const response = await fetch('/api/jobs'); if (response.ok) render((await response.json()).jobs); } catch (_) {}
60	  }
61	  form.addEventListener('submit', async (event) => {
62	    event.preventDefault(); errorRegion.textContent = '';
63	    const payload = { input: field('input').value, steps: Number(field('steps').value), failAttempts: Number(field('failAttempts').value) };
64	    try {
65	      const response = await fetch('/api/jobs', { method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify(payload) });
66	      const data = await response.json();
67	      if (!response.ok) {
68	        const e = data.error || {};
69	        const fieldErrors = Array.isArray(e.fields) ? e.fields.map((x) => `${x.field}: ${x.message}`).join(' ') : '';
70	        errorRegion.textContent = [e.message || 'Submission failed.', fieldErrors].filter(Boolean).join(' ');
71	      } else { form.elements.namedItem('input').value = ''; await refresh(); }
72	    } catch (_) { errorRegion.textContent = 'Unable to submit the job. Please try again.'; }
73	  });
74	  refresh(); setInterval(refresh, 700);
75	})();
76	</script>
77	</body>
